"""The order resolver grants the hero-hub permission to a stale plan row.

g1190 2026-11-18 15:28 (#4546): the pending plan row for the hero→hub move
was adopted before the flag existed; every deploy read it without
hero_hub_move and ハバティー/デーメーテール departed while どうし stayed home.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.strategy import orders as o


def memory():
    gate = chart.gateway(11)
    return {'chapter': 11, 'captured': list(gate['front']) + [gate['hub']],
            'orders': {}, 'world': {'sorties': {}, 'garrison': {gate['hub']: ['キール']}}}


def row(target=None):
    gate = chart.gateway(11)
    return {'step': 'S1', 'general': o.NAME, 'source': 'アルマムーン',
            'target': target or gate['hub'], 'purpose': 'move', 'cards': []}


def test_a_stale_hero_row_to_the_hub_gains_the_permission():
    mem = memory()
    resolved = o._with_hero_hub_permission(mem, row())
    assert resolved['hero_hub_move'] is True
    assert row().get('hero_hub_move') is None    # the source row is untouched


def test_another_general_or_target_is_untouched():
    mem = memory()
    other = {**row(), 'general': 'キール'}
    assert 'hero_hub_move' not in o._with_hero_hub_permission(mem, other)
    elsewhere = row('チリベット')
    assert 'hero_hub_move' not in o._with_hero_hub_permission(mem, elsewhere)


def test_an_enemy_hub_grants_nothing():
    mem = memory()
    mem['captured'] = []
    assert 'hero_hub_move' not in o._with_hero_hub_permission(mem, row())
